(function(){
  if (window.__tirInstalled__) return;
  window.__tirInstalled__ = true;
  var canvas = document.getElementById('tirCanvas');
  var ctx = canvas.getContext('2d');
  var n1Slider = document.getElementById('n1Slider');
  var n1Val = document.getElementById('n1Val');
  var iSlider = document.getElementById('iSlider');
  var iVal = document.getElementById('iVal');
  var out = document.getElementById('tirOut');
  var playBtn = document.getElementById('playBtn');
  var D2R = Math.PI / 180;
  var n2 = 1;
  var running = false, pulse = 0;
  window.simState = { n1: 1.5, i: 30, critical: 0, tir: false, r: 0, running: false };
  function compute(){
    var n1 = parseFloat(n1Slider.value), i = parseFloat(iSlider.value);
    var c = Math.asin(n2 / n1) / D2R;
    var tir = i >= c;
    var r = tir ? NaN : Math.asin((n1 / n2) * Math.sin(i * D2R)) / D2R;
    window.simState.n1 = n1; window.simState.i = i; window.simState.critical = c;
    window.simState.tir = tir; window.simState.r = r;
    return { n1: n1, i: i, c: c, tir: tir, r: r };
  }
  function line(x1, y1, x2, y2, color, width, dash){
    ctx.strokeStyle = color; ctx.lineWidth = width;
    if (dash) ctx.setLineDash(dash); else ctx.setLineDash([]);
    ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke();
    ctx.setLineDash([]);
  }
  function pulseDot(poly, color){
    if (poly.length < 2) return;
    var plen = 0;
    for (var i = 1; i < poly.length; i++) plen += Math.sqrt(Math.pow(poly[i][0] - poly[i-1][0], 2) + Math.pow(poly[i][1] - poly[i-1][1], 2));
    var pos = ((pulse % 1) + 1) % 1 * plen;
    var acc = 0;
    for (var j = 1; j < poly.length; j++) {
      var seg = Math.sqrt(Math.pow(poly[j][0] - poly[j-1][0], 2) + Math.pow(poly[j][1] - poly[j-1][1], 2));
      if (acc + seg >= pos) {
        var t = seg ? (pos - acc) / seg : 0;
        var px = poly[j-1][0] + (poly[j][0] - poly[j-1][0]) * t;
        var py = poly[j-1][1] + (poly[j][1] - poly[j-1][1]) * t;
        ctx.fillStyle = color;
        ctx.beginPath(); ctx.arc(px, py, 4.5, 0, Math.PI * 2); ctx.fill();
        break;
      }
      acc += seg;
    }
  }
  function draw(){
    var s = compute();
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    var YI = 180;
    ctx.fillStyle = '#164e63';
    ctx.fillRect(0, YI, canvas.width, canvas.height - YI);
    ctx.fillStyle = 'rgba(51,65,85,0.4)';
    ctx.fillRect(0, 0, canvas.width, YI);
    ctx.fillStyle = '#7dd3fc'; ctx.font = '12px sans-serif';
    ctx.textAlign = 'left'; ctx.textBaseline = 'top';
    ctx.fillText('الهواء n = 1', canvas.width - 10, 6);
    ctx.textAlign = 'right';
    ctx.fillText('الوسط الكثيف n₁ = ' + s.n1.toFixed(2), canvas.width - 10, YI + 8);
    line(0, YI, canvas.width, YI, '#94a3b8', 2);
    var srcX = 70, srcY = 320;
    var Px = srcX + (YI - srcY) * Math.tan(s.i * D2R);
    var Py = YI;
    line(Px, YI, Px, YI - 80, '#475569', 1, [4, 4]);
    ctx.fillStyle = '#cbd5e1'; ctx.font = '11px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('i', Px + 14, YI - 46);
    var inc = [[srcX, srcY], [Px, Py]];
    line(srcX, srcY, Px, Py, '#facc15', 3);
    var poly = [srcX, srcY, Px, Py];
    if (s.tir) {
      line(Px, Py, Px + 200 * Math.sin(s.i * D2R), Py + 200 * Math.cos(s.i * D2R), '#ef4444', 5);
      poly = poly.concat([Px + 200 * Math.sin(s.i * D2R), Py + 200 * Math.cos(s.i * D2R)]);
      ctx.fillStyle = '#ef4444'; ctx.font = 'bold 13px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('انعكاس كلي', Px - 8, Py - 60);
    } else {
      line(Px, Py, Px + 200 * Math.sin(s.r * D2R), Py - 200 * Math.cos(s.r * D2R), '#60a5fa', 3);
      line(Px, Py, Px + 70 * Math.sin(s.i * D2R), Py + 70 * Math.cos(s.i * D2R), '#f87171', 1.5);
      ctx.fillStyle = '#60a5fa'; ctx.font = 'bold 13px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('r = ' + s.r.toFixed(1) + '°', Px + 90, Py - 110);
      poly = poly.concat([Px + 200 * Math.sin(s.r * D2R), Py - 200 * Math.cos(s.r * D2R)]);
    }
    var path = [];
    for (var q = 0; q < poly.length; q += 2) path.push([poly[q], poly[q + 1]]);
    if (running) pulseDot(path, '#ffffff');
    var y1 = 300, y2 = 340;
    line(30, y1, canvas.width - 30, y1, '#475569', 1.5);
    line(30, y2, canvas.width - 30, y2, '#475569', 1.5);
    ctx.fillStyle = '#94a3b8'; ctx.font = '11px sans-serif';
    ctx.textAlign = 'left'; ctx.textBaseline = 'middle';
    ctx.fillText('ليف بصري', 40, 320);
    if (s.tir) {
      var x = 90, ang = 50, step = 20;
      var fiberPath = [[x, y2 - 12]];
      for (var b = 0; b < 6; b++) {
        var nx = x + (y2 - y1 - 12) / Math.tan(ang * D2R);
        line(x, y2 - 12, nx, y1 + 12, '#22d3ee', 2);
        fiberPath.push([nx, y1 + 12]);
        x = nx;
        var n2x = nx + (y2 - y1 - 12) / Math.tan(ang * D2R);
        line(nx, y1 + 12, n2x, y2 - 12, '#22d3ee', 2);
        fiberPath.push([n2x, y2 - 12]);
        x = n2x;
      }
      if (running) pulseDot(fiberPath, '#fff');
      ctx.fillStyle = '#67e8f9'; ctx.font = '11px sans-serif';
      ctx.textAlign = 'left';
      ctx.fillText('الانعكاس الكلي يُبقي الضوء داخل الليف', 160, 320);
    } else {
      ctx.fillStyle = '#f87171'; ctx.font = '11px sans-serif';
      ctx.textAlign = 'left';
      ctx.fillText('بدون زاوية أكبر من الحرجة: الضوء يخرج من الليف', 160, 320);
      line(90, y2 - 12, 190, y1 - 30, '#f87171', 1.5);
    }
    n1Val.textContent = s.n1.toFixed(2);
    iVal.textContent = s.i + '°';
    out.textContent = 'i = ' + s.i + '° | الزاوية الحرجة c = ' + s.c.toFixed(1) + '° | ' + (s.tir ? 'انعكاس كلي' : 'انكسار (r = ' + s.r.toFixed(1) + '°)');
  }
  playBtn.addEventListener('click', function(){
    running = !running;
    window.simState.running = running;
    playBtn.textContent = running ? 'إيقاف' : 'تشغيل النبضة';
  });
  n1Slider.addEventListener('input', function(){});
  iSlider.addEventListener('input', function(){});
  function fit(){ canvas.style.maxWidth = '100%'; }
  if (!window.__fitInstalled__) { fit(); window.addEventListener('resize', fit); window.__fitInstalled__ = true; }
  function loop(){ if (running) pulse += 0.02; draw(); requestAnimationFrame(loop); }
  loop();
})();
